    "When someone mentions you, uses @here, messages you directly, or replies in a thread you follow. Also reminders you set in a space. Click to open the conversation. Only shown while the app is in the background.": "Quand quelqu’un vous mentionne, utilise @here, vous écrit directement ou répond dans un fil que vous suivez. Aussi pour les rappels créés dans un espace. Cliquez pour ouvrir la conversation. Affiché seulement quand l’app est en arrière-plan.",
    "When your meeting notes finish generating after a call. Click to open the note. Only shown while the app is in the background.": "Quand vos notes de réunion sont prêtes après un appel. Cliquez pour ouvrir la note. Affiché seulement quand l’app est en arrière-plan.",
    "Where coding work lands when you don't name a folder — say \"fix the login bug\" anywhere (Todo, chat, voice) and it runs here on its own isolated branch. Repos are registered in the Code section.": "Où va le travail de code quand vous ne précisez pas de dossier : dites « corrige le bug de connexion » n’importe où (À faire, discussion, voix) et il s’exécute ici sur sa propre branche isolée. Les dépôts s’enregistrent dans la section Code.",
