    "In Auto previews of a stream message, offer @mentions judged from recent messages here. Nothing is added until you click.": "Dans les aperçus Auto d’un message, propose des @mentions déduites des messages récents d’ici. Rien n’est ajouté sans votre clic.",
    "Jev API key removed": "Clé API Jev retirée",
    "Jev API key saved": "Clé API Jev enregistrée",
    "Jev is TypeSafe's System One model: it answers typed questions rather than chat, so it does not appear in the model pickers above. A key adds an Auto toggle beside @djazzi in a space's composer, which lets Jev decide whether a message starts something new or replies to an open thread, and a /find command that jumps to the message you describe. Without a key, nothing changes. Get a key from": "Jev est le modèle System One de TypeSafe : il répond à des questions structurées plutôt qu’en discussion, et n’apparaît donc pas dans les sélecteurs ci-dessus. Une clé ajoute un bouton Auto à côté de la mention de l’assistant dans le champ de saisie d’un espace, qui laisse Jev décider si un message lance un nouveau sujet ou répond à un fil ouvert, ainsi qu’une commande /find qui amène au message que vous décrivez. Sans clé, rien ne change. Obtenez une clé sur",
    "Paste your TypeSafe API key": "Collez votre clé API TypeSafe",
