    "macOS is blocking Screen Recording, so the assistant would only see black frames. Enable Djazzi under System Settings → Privacy & Security → Screen Recording, then relaunch Djazzi. If Djazzi is already enabled there, toggle it off and on — an updated app needs a fresh grant — and relaunch.": "macOS bloque l’enregistrement de l’écran : l’assistant ne verrait qu’une image noire. Activez Djazzi dans Réglages du système → Confidentialité et sécurité → Enregistrement de l’écran, puis relancez Djazzi. Si Djazzi y est déjà activé, désactivez-le puis réactivez-le (une app mise à jour demande une nouvelle autorisation) et relancez.",
    "Screen capture didn’t start, so the assistant can’t see your screen. If you dismissed the picker, just try sharing again. If it keeps failing, restart Djazzi — the call carries on fine without sharing.": "La capture d’écran n’a pas démarré : l’assistant ne peut pas voir votre écran. Si vous avez fermé la fenêtre de choix, relancez simplement le partage. Si cela échoue encore, redémarrez Djazzi : l’appel continue très bien sans partage.",
