    "@keyframes talking-head-bob { 0%, 100% { transform: translateY(0) rotate(-1.6deg); } 50% { transform: translateY(-4px) rotate(1.6deg); } } .talking-head-bob { animation-name: talking-head-bob; animation-timing-function: ease-in-out; animation-iteration-count: infinite; } @keyframes talking-head-ripple { 0% { transform: scale(0.6); opacity: 0.5; } 100% { transform: scale(1.25); opacity: 0; } } .talking-head-ripple { transform-origin: center; transform-box: fill-box; animation: talking-head-ripple 2.6s ease-out infinite; } @keyframes talking-head-bubble { 0%, 100% { opacity: 0.25; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-2px); } } .talking-head-bubble { animation: talking-head-bubble 1.2s ease-in-out infinite; }": "@keyframes talking-head-bob { 0%, 100% { transform: translateY(0) rotate(-1.6deg); } 50% { transform: translateY(-4px) rotate(1.6deg); } } .talking-head-bob { animation-name: talking-head-bob; animation-timing-function: ease-in-out; animation-iteration-count: infinite; } @keyframes talking-head-ripple { 0% { transform: scale(0.6); opacity: 0.5; } 100% { transform: scale(1.25); opacity: 0; } } .talking-head-ripple { transform-origin: center; transform-box: fill-box; animation: talking-head-ripple 2.6s ease-out infinite; } @keyframes talking-head-bubble { 0%, 100% { opacity: 0.25; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-2px); } } .talking-head-bubble { animation: talking-head-bubble 1.2s ease-in-out infinite; }",
