    "After a meeting's notes are ready, scan them for coding action items (bugs to fix, features to build, concrete changes requested) for me or my team. Conservatively implement the clearly-scoped, self-contained ones in the configured repo using the launch-code-task tool — group related items into one session, split unrelated ones. Note ambiguous, large/architectural, or other-repo items as \"needs review\" instead of coding them. If nothing is actionable, do nothing.": "Quand les notes d’une réunion sont prêtes, y repérer les actions de code (bugs à corriger, fonctionnalités à construire, changements concrets demandés) pour moi ou mon équipe. Réaliser prudemment, dans le dépôt configuré avec l’outil launch-code-task, celles qui sont bien délimitées et autonomes : regrouper les éléments liés dans une même session, séparer les autres. Noter « à examiner » les éléments ambigus, trop gros, d’architecture ou d’un autre dépôt au lieu de les coder. S’il n’y a rien à faire, ne rien faire.",
