    "Morning planner": "Planificateur du matin",
    "Morning summary": "Résumé du matin",
    "Every day · Email, calendar": "Chaque jour · E-mail, agenda",
    "Prepare my meetings": "Préparer mes réunions",
    "Every evening · Calendar": "Chaque soir · Agenda",
    "Meeting minutes": "Compte rendu de réunion",
    "After each meeting": "Après chaque réunion",
    "Important emails": "E-mails importants",
    "Each email · Email": "À chaque e-mail · E-mail",
    "Keep watch on a topic": "Veille sur un sujet",
    "Every week · Web": "Chaque semaine · Web",
    "Weekly review": "Bilan de la semaine",
    "Every Friday · To-do": "Chaque vendredi · Tâches",
    // The to-do list the app writes on the first run (core todo/fileops.ts SEED), and the usage panel (02/10/2026).
    "Add your first to-do — just type below": "Ajoutez votre première chose à faire : écrivez-la juste en dessous",
    "introduce yourself — what can you do here?": "présente-toi : que peux-tu faire ici ?",
    "Dismiss anything you don't want — hover a row and hit ✕ (it lands in Done & dismissed below, restorable)": "Retirez ce dont vous ne voulez pas : survolez la ligne et cliquez ✕ (elle va dans « Fait et écarté », plus bas, et peut revenir)",
    "Last updated: just now": "Dernière mise à jour : à l’instant",
    // The first to-do list, as the app wrote it before it was French (02/10/2026).
    "@rowboat introduce yourself — what can you do here?": "@djazzi présente-toi : que peux-tu faire ici ?",
    // Barre, Utilisation, visite, tâches préremplies (03/10/2026)
    "I'm your captain for the next minute. The lights are down and the water's in, so let me row you across Djazzi, one stop at a time. Use Next or your arrow keys.": "Je vous fais visiter Djazzi en une minute, une étape à la fois. Avancez avec Suivant ou avec les flèches du clavier.",
    "I'm your captain for the next minute. The lights are down and the water's in, so let me row you across Djazzi, one stop at a time.": "Je vous fais visiter Djazzi en une minute, une étape à la fois.",
    "Every morning at 7, send me a short brief of my day. Start with today's meetings: the time, who will be there and what it is about. Then the unread emails that need me, from clients, suppliers and partners first, each in one line with what is expected of me. End with the three things I should do first, in order. Leave out newsletters and notifications. Keep it under fifteen lines.": "Chaque matin à 7 h, envoie-moi un court point sur ma journée. Commence par les réunions du jour : l’heure, avec qui, et de quoi il s’agit. Puis les e-mails non lus qui m’attendent, ceux des clients, des fournisseurs et des partenaires d’abord, chacun en une ligne avec ce qu’on attend de moi. Termine par les trois choses à faire en premier, dans l’ordre. Laisse de côté les lettres d’information et les notifications. Pas plus de quinze lignes.",
    "Every evening at 6, prepare tomorrow's meetings. For each one: the time and the people attending, what we said or decided the last time (from my notes and emails), what is still open between us, and three questions I should ask. If a document should be read beforehand, tell me which one. Skip reminders and blocked time slots.": "Chaque soir à 18 h, prépare les réunions de demain. Pour chacune : l’heure et les participants, ce qu’on s’est dit ou décidé la dernière fois (d’après mes notes et mes e-mails), ce qui reste en suspens entre nous, et trois questions à poser. S’il faut lire un document avant, dis-moi lequel. Ignore les rappels et les simples créneaux bloqués.",
    "When a meeting's notes are ready, write the minutes. At the top, in two sentences, what the meeting was for and how it ended. Then the decisions taken, then the actions: who does what, and by when. Put my own actions first so I can add them to my list. Do not send anything to the participants: I read it first.": "Quand les notes d’une réunion sont prêtes, rédige le compte rendu. En haut, en deux phrases, l’objet de la réunion et comment elle s’est terminée. Puis les décisions prises, puis les actions : qui fait quoi, et pour quand. Mets mes propres actions en premier pour que je les ajoute à ma liste. N’envoie rien aux participants : je relis d’abord.",
    "When a client, a supplier or a partner writes to me, sum up their message in two lines: what they want and by when. Then prepare a draft reply in my tone, polite and short, that answers each of their questions. If something is missing to reply, such as a price, a date or a document, tell me what. Never send the reply: leave it as a draft.": "Quand un client, un fournisseur ou un partenaire m’écrit, résume son message en deux lignes : ce qu’il veut et pour quand. Puis prépare un brouillon de réponse dans mon ton, poli et court, qui répond à chacune de ses questions. S’il manque quelque chose pour répondre, comme un prix, une date ou un document, dis-moi quoi. N’envoie jamais la réponse : laisse-la en brouillon.",
    "Every Monday at 8, look in my emails for the invoices and quotes I sent that have had no answer or payment for more than 7 days. List them with the client, the amount and the date sent. For each one, prepare a polite reminder as a draft, firmer if it is the second reminder. Never send anything yourself.": "Chaque lundi à 8 h, cherche dans mes e-mails les factures et les devis envoyés restés sans réponse ni paiement depuis plus de 7 jours. Liste-les avec le client, le montant et la date d’envoi. Pour chacun, prépare une relance polie en brouillon, plus ferme si c’est la deuxième relance. N’envoie jamais rien toi-même.",
    "Every Wednesday at 10, find in my emails the clients I have not written to for more than a month after an order or a quote. For each one, suggest a short message to keep in touch, such as news, a new product or a thank-you, as a draft. Five clients at most.": "Chaque mercredi à 10 h, trouve dans mes e-mails les clients à qui je n’ai pas écrit depuis plus d’un mois, après une commande ou un devis. Pour chacun, propose un court message pour garder le contact, comme une nouvelle, un nouveau produit ou un merci, en brouillon. Cinq clients au plus.",
    "Every Friday at 9, search the web for what was said this week about [my sector, my competitors, my city]. Keep only what can change my business: new prices, new rules, new competitors, opportunities and calls for tenders. Sum it up in five points at most, each with its source and its date. If nothing important happened, say so in one line.": "Chaque vendredi à 9 h, cherche sur le web ce qui s’est dit cette semaine sur [mon secteur, mes concurrents, ma ville]. Garde seulement ce qui peut changer mon activité : nouveaux prix, nouvelles règles, nouveaux concurrents, occasions et appels d’offres. Résume en cinq points au plus, chacun avec sa source et sa date. S’il ne s’est rien passé d’important, dis-le en une ligne.",
    "Every Friday at 5 pm, review my week. What got done, from my to-do list and my sent emails. What is left on the list, and what has been waiting for more than a week. Who I promised something to and have not answered yet. End with the three priorities I should set for next week.": "Chaque vendredi à 17 h, fais le bilan de ma semaine. Ce qui a été fait, d’après ma liste de tâches et mes e-mails envoyés. Ce qui reste sur la liste, et ce qui attend depuis plus d’une semaine. À qui j’ai promis quelque chose sans avoir encore répondu. Termine par les trois priorités à fixer pour la semaine prochaine.",
    "Chase unpaid invoices": "Relancer les factures impayées",
