    "Claude Code runs on it. It goes to the agent's environment on Maritime and nowhere else; Djazzi keeps no copy.": "Claude Code s’en sert. Elle va dans l’environnement de l’agent sur Maritime et nulle part ailleurs ; Djazzi n’en garde aucune copie.",
