    "Create a workspace API key in Attio with object_configuration:read and record_permission:read permissions. Harbor checks it with Attio and keeps it sealed. Anyone who can mention this bot can read CRM data available to its key; replies are visible to everyone in that space.": "Créez dans Attio une clé API d’espace de travail avec les permissions object_configuration:read et record_permission:read. Harbor la vérifie auprès d’Attio et la garde scellée. Quiconque peut mentionner ce bot peut lire les données CRM accessibles à sa clé ; ses réponses sont visibles de tous dans l’espace.",
