    "Every message, file and membership in this space is deleted for everyone. This cannot be undone. Type the space name to confirm.": "Tous les messages, fichiers et membres de cet espace sont supprimés pour tout le monde. C’est irréversible. Tapez le nom de l’espace pour confirmer.",
