    "For a project or a team. Share its link on WhatsApp, LinkedIn or mail; whoever opens it is in.": "Pour un projet ou une équipe. Partagez son lien sur WhatsApp, LinkedIn ou par e-mail ; qui l’ouvre est dedans.",
