    "Give a thread a title from its ⋯ menu, or type /discussion in a reply, and it shows up here.": "Donnez un titre à un fil depuis son menu ⋯, ou tapez /discussion dans une réponse, et il apparaît ici.",
    "Give it the Spaces tools (optional)": "Lui donner les outils des Espaces (facultatif)",
