    "Half-life:": "Demi-vie :",
    "Harbor checks it with Agent37 and keeps it sealed. A key reaches every instance in its Agent37 workspace (there are no per-instance keys), so make one just for Djazzi.": "Harbor la vérifie auprès d’Agent37 et la garde scellée. Une clé atteint toutes les instances de son espace de travail Agent37 (il n’y a pas de clé par instance) : créez-en une rien que pour Djazzi.",
    "Harbor checks it with Replicas and keeps it sealed. Nobody sees it again, you included.": "Harbor la vérifie auprès de Replicas et la garde scellée. Personne ne la revoit, vous compris.",
    "Has": "Contient",
    "Has details": "A des détails",
    "Have an invite link, or your own server?": "Vous avez un lien d’invitation, ou votre propre serveur ?",
    "Have an invite link?": "Vous avez un lien d’invitation ?",
    "Header: Authorization": "En-tête : Authorization",
    "Heaviest": "Les plus lourds",
    "Hermes": "Hermes",
    "Hermes or OpenClaw on an Agent37 instance, on your Agent37 account": "Hermes ou OpenClaw sur une instance Agent37, sur votre compte Agent37",
    "Hermes, Claude Code or Codex in a Maritime VM, on your Maritime account": "Hermes, Claude Code ou Codex dans une machine virtuelle Maritime, sur votre compte Maritime",
    "Hermes, Replicas, Conductor, Agent37, Maritime, or a custom agent.": "Hermes, Replicas, Conductor, Agent37, Maritime, ou un agent personnalisé.",
    "Hermes, a coding agent in Replicas or Conductor, or anything that speaks the agent contract, or a bot for PostHog or Cal.com.": "Hermes, un agent de code dans Replicas ou Conductor, tout ce qui respecte le contrat d’agent, ou un bot pour PostHog ou Cal.com.",
    "Hide details": "Masquer les détails",
    "Hide spaces": "Masquer les espaces",
    "How fast old activity stops counting.": "À quelle vitesse l’ancienne activité cesse de compter.",
    "How it appears in Spaces, and what people type to mention it.": "Comment il apparaît dans les Espaces, et ce qu’on tape pour le mentionner.",
    "How it connects": "Comment il se connecte",
    "How it should behave. It reads this before every request. You are Scout, the team’s reviewer. Be brief…": "Comment il doit se comporter. Il le lit avant chaque demande. Tu es Scout, le relecteur de l’équipe. Sois bref…",
    "Idle": "Inactif",
    "Importance": "Importance",
    "Important threads count more": "Les fils importants comptent davantage",
    "In Cal.com, Settings → Developer → Webhooks → New, with this as the Subscriber URL and the booking events you want. Ping test posts a hello.": "Dans Cal.com, Settings → Developer → Webhooks → New, avec ceci comme Subscriber URL et les événements de réservation voulus. Le test ping envoie un bonjour.",
    "In Replicas, open the environment this agent will use (not Global), then MCPs → Add server. Give each Djazzi agent its own environment: the server acts as this agent.": "Dans Replicas, ouvrez l’environnement que cet agent utilisera (pas Global), puis MCPs → Add server. Donnez à chaque agent Djazzi son propre environnement : le serveur agit en tant que cet agent.",
    "In a terminal where Hermes runs. Not in a chat: Hermes never needs to see its key.": "Dans un terminal où tourne Hermes. Pas dans une discussion : Hermes n’a jamais besoin de voir sa clé.",
    "In a terminal where Hermes runs. This points it at this org, gives it the Spaces tools, lets you run Hermes commands from Spaces, and keeps its progress chatter out of threads.": "Dans un terminal où tourne Hermes. Cela le dirige vers ce serveur, lui donne les outils des Espaces, vous laisse lancer des commandes Hermes depuis les Espaces, et garde ses messages de progression hors des fils.",
    "In the same environment, add these as variables (the key as a secret).": "Dans le même environnement, ajoutez ceci comme variables (la clé comme secret).",
    "In the same environment’s Skills tab, add this repository as a skill registry. Its rowboat-spaces skill teaches the agent how to behave in Spaces: mentions, hand-offs, threads.": "Dans l’onglet Skills du même environnement, ajoutez ce dépôt comme registre de compétences. Sa compétence rowboat-spaces apprend à l’agent à se comporter dans les Espaces : mentions, passages de relais, fils.",
    "Include": "Inclure",
    "Info": "Info",
    "Install the Djazzi plugin": "Installer l’extension Djazzi",
    "Install the Djazzi plugin and skill": "Installer l’extension et la compétence Djazzi",
    "Installed": "Installé",
    "Installed skills": "Compétences installées",
    "Instance": "Instance",
    "Invite to #": "Inviter dans #",
    "It edits files and runs commands without asking.": "Il modifie des fichiers et lance des commandes sans demander.",
    "It needs Jev, the model that judges what each thread is about, and this server has no key for it.": "Il faut Jev, le modèle qui juge de quoi parle chaque fil, et ce serveur n’a pas de clé pour lui.",
    "It reads freely; edits and commands wait for you in the thread.": "Il lit librement ; les modifications et les commandes vous attendent dans le fil.",
    "It reads its personality before every request. Changes apply from the next mention.": "Il lit sa personnalité avant chaque demande. Les changements s’appliquent dès la prochaine mention.",
    "It runs on your computer, so only you can ask it, wherever it is added. Others see it and its replies. It answers while Djazzi is open here.": "Il tourne sur votre ordinateur : vous seul pouvez lui demander, où qu’il soit ajouté. Les autres le voient, lui et ses réponses. Il répond tant que Djazzi est ouvert ici.",
    "It saves the rest, installs the Djazzi plugin, and tells you when it’s done. If it can’t, use Terminal or Dashboard above instead.": "Il enregistre le reste, installe l’extension Djazzi, et vous prévient quand c’est fait. S’il n’y arrive pas, utilisez plutôt Terminal ou Tableau de bord ci-dessus.",
    "It stops on this computer, leaves every space and loses its keys. Its messages and your folder stay.": "Il s’arrête sur cet ordinateur, quitte tous les espaces et perd ses clés. Ses messages et votre dossier restent.",
    "It stops seeing this space and answering here. What it wrote stays.": "Il cesse de voir cet espace et d’y répondre. Ce qu’il a écrit reste.",
    "It teaches Hermes how to behave in Spaces: mentions, hand-offs, threads. Run it where Hermes runs, or ask your Hermes to run it.": "Elle apprend à Hermes à se comporter dans les Espaces : mentions, passages de relais, fils. Lancez-la là où tourne Hermes, ou demandez à votre Hermes de la lancer.",
    "It's just you here so far. Bring in the people and the agents who should work on this, then say what it's for.": "Pour l’instant, vous êtes seul ici. Faites venir les personnes et les agents qui doivent y travailler, puis dites à quoi il sert.",
