    "Machine": "Machine",
    "Make admin of": "Rendre admin de",
    "Make it a plain thread": "En faire un fil simple",
    "Make it in your Conductor team org (Pro or higher), which needs a Claude key or subscription under Settings → Agents, and GitHub repositories. Harbor checks it with Conductor and keeps it sealed. Nobody sees it again, you included.": "Créez-la dans l’organisation de votre équipe Conductor (Pro ou plus), qui demande une clé ou un abonnement Claude sous Settings → Agents, et des dépôts GitHub. Harbor la vérifie auprès de Conductor et la garde scellée. Personne ne la revoit, vous compris.",
    "Make this a session…": "En faire une session…",
    "Manage membership and who can administer this space.": "Gérer les membres et qui peut administrer cet espace.",
    "Manage the agents here and who can ask them to work.": "Gérer les agents ici et qui peut leur demander de travailler.",
    "Manage your status and notifications on each server.": "Gérez votre statut et vos notifications sur chaque serveur.",
    "Maritime": "Maritime",
    "Maritime API key": "Clé API Maritime",
    "Maritime agent": "Agent Maritime",
    "Maritime could not be asked about the machine just now.": "Impossible d’interroger Maritime sur la machine pour l’instant.",
    "Maritime doesn’t say what this agent runs. Which is it?": "Maritime ne dit pas ce que cet agent exécute. Lequel est-ce ?",
    "Maritime gave no reason": "Maritime n’a donné aucune raison",
    "Maritime runs the prompt on the schedule, inside the VM. The agent's reply goes where the prompt says, through its Spaces tools; name the space. Times are UTC.": "Maritime lance l’instruction selon le calendrier, dans la machine virtuelle. La réponse de l’agent va là où l’instruction le dit, par ses outils Espaces ; nommez l’espace. Heures en UTC.",
    "Maritime's logs for the VM, newest first.": "Les journaux de Maritime pour la machine, les plus récents d’abord.",
    "Member details and actions": "Détails et actions du membre",
    "Member type": "Type de membre",
    "Members can still read it, but nobody can post, upload or change anything until an admin unarchives it.": "Les membres peuvent encore le lire, mais personne ne peut publier, envoyer ou modifier quoi que ce soit tant qu’un admin ne l’a pas désarchivé.",
    "Mention the bot with help for its commands. It reads Attio with your workspace key and replies in the thread. Use its current name if you rename it.": "Mentionnez le bot avec help pour ses commandes. Il lit Attio avec la clé de votre espace de travail et répond dans le fil. Utilisez son nom actuel si vous le renommez.",
