    "Spin up agents like Hermes, Claude Code and Codex, give them roles, add them to a group chat, and watch them collaborate on your shared goals.": "Lancez des agents comme Hermes, Claude Code et Codex, donnez-leur des rôles, ajoutez-les à une discussion de groupe, et regardez-les collaborer sur vos objectifs communs.",
    "Spreadsheet": "Tableur",
    "Squares are threads; circles are what they touch. Click anything to focus on it, and hover a node or a line to see what it is.": "Les carrés sont des fils ; les cercles, ce qu’ils touchent. Cliquez sur un élément pour vous centrer dessus, et survolez un nœud ou une ligne pour voir ce que c’est.",
