    "The agent": "L’agent",
    "The agent is one Agent37 instance, with its own memory and files. Pick one this key reaches, or create one. It can’t be changed later.": "L’agent est une instance Agent37, avec sa propre mémoire et ses fichiers. Choisissez-en une que cette clé atteint, ou créez-en une. Ce choix est définitif.",
    "The agent is one Maritime agent, a VM with its own files and memory. Pick one this key reaches. It can’t be changed later.": "L’agent est un agent Maritime, une machine virtuelle avec ses propres fichiers et sa mémoire. Choisissez-en un que cette clé atteint. Ce choix est définitif.",
    "The computer that runs it holds its key. Running it on another computer makes a new key there and revokes this one.": "L’ordinateur qui le fait tourner détient sa clé. Le faire tourner sur un autre ordinateur crée une nouvelle clé là-bas et révoque celle-ci.",
    "The folder it opens on this computer. You can change it later from its page.": "Le dossier qu’il ouvre sur cet ordinateur. Vous pourrez le changer depuis sa page.",
    "The graph is not available on this server": "Le graphe n’est pas disponible sur ce serveur",
    "The graph is off for this space": "Le graphe est désactivé pour cet espace",
    "The key goes to": "La clé va à",
    "The key needs the deploy, secrets and manage scopes (Maritime → Settings → API keys). Revoking it on Maritime stops the agent at once; replace it on this page.": "La clé a besoin des portées deploy, secrets et manage (Maritime → Settings → API keys). La révoquer sur Maritime arrête l’agent aussitôt ; remplacez-la sur cette page.",
    "The rowboat-spaces skill teaches it how to behave in Spaces: mentions, hand-offs, threads.": "La compétence rowboat-spaces lui apprend à se comporter dans les Espaces : mentions, passages de relais, fils.",
    "The rowboat-spaces skill teaches it how to behave in Spaces: mentions, hand-offs, threads. Run this in the repository and commit what it adds.": "La compétence rowboat-spaces lui apprend à se comporter dans les Espaces : mentions, passages de relais, fils. Lancez ceci dans le dépôt et validez ce qu’il ajoute.",
    "The server, for the agent contract (list, acknowledge and report its invocations, reply in the thread), and its MCP tools.": "Le serveur, pour le contrat d’agent (lister, accuser réception et rendre compte de ses demandes, répondre dans le fil), et ses outils MCP.",
    "The skill teaches it how to behave in Spaces: mentions, hand-offs, threads.": "La compétence lui apprend à se comporter dans les Espaces : mentions, passages de relais, fils.",
    "The trial ends the moment it is saved.": "L’essai s’arrête dès l’enregistrement.",
    "They and their agents leave this space. Their existing messages stay.": "Eux et leurs agents quittent cet espace. Leurs messages restent.",
    "They stop seeing this space, and their agents leave with them. What they wrote stays; someone in the space can invite them back.": "Cette personne ne voit plus cet espace, et ses agents partent avec elle. Ce qu’elle a écrit reste ; quelqu’un de l’espace peut la réinviter.",
    "This Spaces server names no sign-in provider.": "Ce serveur d’Espaces n’indique aucun fournisseur de connexion.",
